#!/usr/bin/env bash
set -euo pipefail

echo "Configurando Token Monitor Jean..."

mkdir -p '.github/workflows'
printf %s '' | base64 -d > '.github/workflows/build-apk.yml'

printf %s '' | base64 -d > 'README.md'

mkdir -p 'app'
printf %s '' | base64 -d > 'app/build.gradle'

mkdir -p 'app/src/main'
printf %s '' | base64 -d > 'app/src/main/AndroidManifest.xml'

mkdir -p 'app/src/main/java/com/jean/tokenmonitor'
printf %s '' | base64 -d > 'app/src/main/java/com/jean/tokenmonitor/MainActivity.java'

printf %s 'cGx1Z2lucyB7CiAgICBpZCAnY29tLmFuZHJvaWQuYXBwbGljYXRpb24nIHZlcnNpb24gJzkuNC4wJyBhcHBseSBmYWxzZQp9Cg==' | base64 -d > 'build.gradle'

printf %s 'b3JnLmdyYWRsZS5qdm1hcmdzPS1YbXgyMDQ4bSAtRGZpbGUuZW5jb2Rpbmc9VVRGLTgKYW5kcm9pZC51c2VBbmRyb2lkWD1mYWxzZQo=' | base64 -d > 'gradle.properties'

printf %s '' | base64 -d > 'settings.gradle'

git config user.name "Token Monitor Setup"
git config user.email "tokenmonitor@users.noreply.github.com"
git add README.md build.gradle gradle.properties settings.gradle app .github
git commit -m "Adicionar app Token Monitor Jean" || true
git push origin HEAD

echo "Projeto enviado. Abra a aba Actions e aguarde o workflow Build Android APK."